3	/**
4	 * Tracks active upstream generation requests so they can be cancelled on demand.
5	 * Multiple controllers can be registered per conversation (for threaded/background runs).
6	 */
7	export class AbortRegistry {
8		private static instance: AbortRegistry;
9	
10		private controllers = new Map<string, Set<AbortController>>();
11	
12		public static getInstance(): AbortRegistry {
13			if (!AbortRegistry.instance) {
14				AbortRegistry.instance = new AbortRegistry();
15			}
16			return AbortRegistry.instance;
17		}
18	
19		public register(conversationId: string, controller: AbortController) {
20			const key = conversationId.toString();
21			let set = this.controllers.get(key);
22			if (!set) {
23				set = new Set();
24				this.controllers.set(key, set);
25			}
26			set.add(controller);
27			controller.signal.addEventListener(
28				"abort",
29				() => {
30					this.unregister(key, controller);
31				},
32				{ once: true }
33			);
34		}
35	
36		public abort(conversationId: string) {
37			const set = this.controllers.get(conversationId);
38			if (!set?.size) return;
39	
40			logger.debug({ conversationId }, "Aborting active generation via AbortRegistry");
41			for (const controller of set) {
42				if (!controller.signal.aborted) {
43					controller.abort();
44				}
45			}
46			this.controllers.delete(conversationId);
47		}
48	
49		public unregister(conversationId: string, controller: AbortController) {
50			const set = this.controllers.get(conversationId);
51			if (!set) return;
52			set.delete(controller);
53			if (set.size === 0) {
54				this.controllers.delete(conversationId);
55			}
56		}
