527	    const entry = this.cache.get(key);
528	    if (!entry) {
529	      this.misses++;
530	      return undefined;
531	    }
532	    if (Date.now() > entry.expiry) {
533	      this.cache.delete(key);
534	      this.misses++;
535	      return undefined;
536	    }
537	    this.hits++;
538	    // Move to end (most recently used)
539	    this.cache.delete(key);
540	    this.cache.set(key, entry);
541	    return entry.value;
542	  }
