545	    if (this.cache.size >= this.maxSize) {
546	      // Remove oldest (first) entry
547	      const firstKey = this.cache.keys().next().value;
548	      if (firstKey !== undefined) {
549	        this.cache.delete(firstKey);
550	      }
551	    }
552	    this.cache.set(key, {
553	      value,
554	      expiry: Date.now() + (ttl ?? this.defaultTTL),
555	    });
556	  }
