1	/**
2	 * Rate Limiter for TeammateTool operations
3	 *
4	 * Implements sliding window rate limiting to prevent abuse
5	 * and ensure fair resource distribution across teammates.
6	 *
7	 * @module @claude-flow/teammate-plugin/utils/rate-limiter
8	 */
9	
10	import type { RateLimitConfig, RateLimitState } from '../types.js';
11	
12	/**
13	 * Rate limiter with configurable per-operation limits
14	 */
15	export class RateLimiter {
16	  private windows: Map<string, RateLimitState> = new Map();
17	  private readonly windowMs = 60000; // 1 minute window
18	
19	  constructor(private config: RateLimitConfig) {}
20	
21	  /**
22	   * Check if operation is allowed under rate limit
23	   */
24	  checkLimit(operation: keyof RateLimitConfig): boolean {
25	    const limit = this.config[operation];
26	    const now = Date.now();
27	    const state = this.windows.get(operation);
28	
29	    if (!state || now - state.windowStart >= this.windowMs) {
30	      // New window
31	      this.windows.set(operation, {
32	        operation,
33	        count: 1,
34	        windowStart: now,
35	        blocked: false,
36	      });
37	      return true;
38	    }
39	
40	    if (state.count >= limit) {
41	      state.blocked = true;
42	      state.nextAllowedAt = state.windowStart + this.windowMs;
43	      return false;
44	    }
45	
46	    state.count++;
47	    return true;
48	  }
49	
50	  /**
51	   * Get current state for an operation
52	   */
53	  getState(operation: string): RateLimitState | undefined {
54	    return this.windows.get(operation);
55	  }
56	
57	  /**
58	   * Reset rate limit for an operation
59	   */
60	  reset(operation?: string): void {
61	    if (operation) {
62	      this.windows.delete(operation);
63	    } else {
64	      this.windows.clear();
65	    }
66	  }
67	
68	  /**
69	   * Get remaining quota for an operation
70	   */
71	  getRemaining(operation: keyof RateLimitConfig): number {
72	    const limit = this.config[operation];
73	    const state = this.windows.get(operation);
74	    if (!state) return limit;
75	    return Math.max(0, limit - state.count);
76	  }
77	
78	  /**
79	   * Get window duration in milliseconds
80	   */
81	  getWindowMs(): number {
82	    return this.windowMs;
83	  }
84	
85	  /**
86	   * Check if an operation is currently blocked
87	   */
88	  isBlocked(operation: keyof RateLimitConfig): boolean {
89	    const state = this.windows.get(operation);
90	    return state?.blocked ?? false;
91	  }
92	
93	  /**
94	   * Get time until rate limit resets for an operation
95	   */
96	  getTimeUntilReset(operation: keyof RateLimitConfig): number {
97	    const state = this.windows.get(operation);
98	    if (!state) return 0;
99	    const remaining = (state.windowStart + this.windowMs) - Date.now();
100	    return Math.max(0, remaining);
101	  }
102	}
